var ua="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36";
var roots=[];
function pushRoot(v){
    v=String(v||"").replace(/\/+$/,"");
    if(!v)return;
    for(var i=0;i<roots.length;i++)if(roots[i]===v)return;
    roots.push(v);
}
