function decode(v){
    return String(v||"")
        .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,"$1")
        .replace(/&amp;/gi,"&")
        .replace(/&lt;/gi,"<")
        .replace(/&gt;/gi,">")
        .replace(/&quot;/gi,'"')
        .replace(/&#39;/gi,"'")
        .replace(/&#x2F;/gi,"/")
        .replace(/&#(\d+);/g,function(_,n){try{return String.fromCharCode(Number(n));}catch(e){return _;}});
}
function text(v){
    return decode(String(v||"").replace(/<[^>]+>/g," ")).replace(/\s+/g," ").replace(/^\s+|\s+$/g,"");
}
function tag(block,name){
    var re=new RegExp("<"+name+"\\b[^>]*>([\\s\\S]*?)<\\/"+name+">","i");
    var m=String(block||"").match(re);
    return m?decode(m[1]):"";
}
function toBytes(v){
    var m=String(v||"").match(/([0-9]+(?:\.[0-9]+)?)\s*(TB|GB|MB|KB|B)/i);
    if(!m)return 0;
    var n=Number(m[1]||0),u=String(m[2]||"B").toUpperCase(),pow=0;
    if(u==="KB")pow=1;else if(u==="MB")pow=2;else if(u==="GB")pow=3;else if(u==="TB")pow=4;
    return Math.round(n*Math.pow(1024,pow));
}
function sizeFromDesc(v){
    var d=decode(v),m=d.match(/([0-9]+(?:\.[0-9]+)?)\s*(TB|GB|MB|KB|B)/i);
    return m?m[1]+" "+String(m[2]).toUpperCase():"";
}
function hashOf(v){
    var m=String(v||"").match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    return m?String(m[1]).toUpperCase():"";
}
function parse(xml){
    xml=String(xml||"");
    if(!xml||!/<rss\b|<channel\b/i.test(xml))return[];
    var out=[],seen={},re=/<item\b[\s\S]*?<\/item>/gi,m;
    while((m=re.exec(xml))!==null){
        var b=m[0],title=text(tag(b,"title")),mag=String(tag(b,"link")||"").replace(/^\s+|\s+$/g,""),guid=String(tag(b,"guid")||"").replace(/^\s+|\s+$/g,""),date=text(tag(b,"pubDate")),desc=tag(b,"description");
        if(mag.indexOf("magnet:?")!==0){
            var mm=b.match(/magnet:\?xt=urn:btih:[^<"'\s]+/i);
            if(mm)mag=decode(mm[0]);
        }
        if(!mag||mag.indexOf("magnet:?")!==0)continue;
        var h=hashOf(mag),key=h||mag;
        if(seen[key])continue;
        seen[key]=1;
        var st=sizeFromDesc(desc);
        var meta=[];
        if(st)meta.push(st);
        if(date)meta.push(date);
        out.push({
            title:title||"未命名资源",
            magnet:mag,
            url:guid||mag,
            bytes:toBytes(st),
            seeders:-1,
            peers:-1,
            date:date,
            desc:meta.join(" · ")
        });
        if(out.length>=60)break;
    }
    return out;
}

var last="";
for(var r=0;r<roots.length;r++){
    var root=roots[r];
    var url=root+"/search?q="+encodeURIComponent(q)+"&orderby=relevance&category=all&p="+p+"&page=rss";
    try{
        var xml=String(request(url,{headers:{
            "User-Agent":ua,
            "Accept":"application/rss+xml,application/xml,text/xml;q=0.9,*/*;q=0.8",
            "Accept-Language":"zh-CN,zh;q=0.9,en;q=0.6",
            "Referer":root+"/"
        },timeout:7500})||"");
        if(/captcha|cloudflare|access denied|forbidden|recaptcha|challenge/i.test(xml)){
            last=root+"：触发网页验证";
            continue;
        }
        var list=parse(xml);
        if(list.length)return list;
        if(/<rss\b|<channel\b/i.test(xml)){
            if(/<item\b/i.test(xml))last=root+"：RSS 有 item 但未提取到 magnet";
            else return [];
        }else{
            last=root+"：返回内容不是 RSS/XML";
        }
    }catch(e){
        last=root+"："+(e.message||e);
    }
}
throw new Error("BT4G 搜索失败"+(last?"（"+last+"）":""));
